const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;
if (!secret || secret.length < 32) throw new Error('LENDLOOP_SHARED_SECRET is missing or too short');
function sign(method, path, body) {
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = crypto.createHmac('sha256', secret)
    .update(`${timestamp}.${method}.${path}.${body}`).digest('hex');
  return { timestamp, signature };
}

// Convex signs `${timestamp}.POST./webhook/lendloop-request.${rawBody}`.
// n8n gives us the parsed body; Convex sends compact JSON.stringify output,
// so re-serializing reproduces the exact bytes that were signed.
const item = $input.first().json;
const headers = item.headers || {};
const body = JSON.stringify(item.body);
const ts = headers['x-lendloop-timestamp'];
const sig = String(headers['x-lendloop-signature'] || '');
let valid = false;
if (ts && Math.abs(Date.now() / 1000 - Number(ts)) <= 300) {
  const expected = crypto.createHmac('sha256', secret)
    .update(`${ts}.POST./webhook/lendloop-request.${body}`).digest('hex');
  valid = expected.length === sig.length &&
    crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(sig));
}

// Drop duplicate deliveries of the same event (Convex retries on timeouts).
let duplicate = false;
if (valid) {
  const store = $getWorkflowStaticData('global');
  store.seen = store.seen || [];
  duplicate = store.seen.includes(item.body.eventId);
  if (!duplicate) store.seen = [...store.seen.slice(-499), item.body.eventId];
}
return [{ json: { valid, duplicate, event: valid ? item.body : null } }];

// Data minimization: build the message from the few fields we received.
const e = $input.first().json.event;
const lines = {
  'loan.requested': `${e.counterpartyFirstName} asked to borrow your ${e.toolName} (${e.startDate} to ${e.endDate}).`,
  'loan.approved':  `${e.counterpartyFirstName} approved your request for the ${e.toolName} (${e.startDate} to ${e.endDate}).`,
  'loan.declined':  `Your request for the ${e.toolName} was declined.`,
  'loan.cancelled': `The request for your ${e.toolName} was cancelled.`,
  'loan.returned':  `The ${e.toolName} was marked returned. Thanks for borrowing responsibly!`,
};
return [{ json: {
  eventId: e.eventId,
  loanId: e.loanId,
  to: e.recipient.email,
  subject: 'LendLoop update',
  text: `Hi ${e.recipient.firstName}, ${lines[e.event] || 'your loan was updated.'}`,
} }];

// Mock notification channel. Swap this node for Send Email / Slack / Discord.
// Only the first name and message are logged; the email address is masked.
const m = $input.first().json;
const masked = m.to ? m.to.replace(/^(.).*(@.*)$/, '$1***$2') : 'no email';
console.log(`[LendLoop notify] to=${masked} :: ${m.text}`);
return [{ json: { ...m, delivered: true } }];

